import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Чат, сообщения и пинги","description":"","frontmatter":{"pageId":"players/chat-pings","contentRevision":1},"headers":[],"relativePath":"ru/players/chat-pings.md","filePath":"ru/players/chat-pings.md"}'),l={name:"ru/players/chat-pings.md"};function o(s,a,n,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="чат-сообщения-и-пинги" tabindex="-1">Чат, сообщения и пинги <a class="header-anchor" href="#чат-сообщения-и-пинги" aria-label="Permalink to &quot;Чат, сообщения и пинги&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Публичный чат виден участникам сервера. Личное сообщение адресуется конкретному игроку. Чат союза доступен текущим участникам союза; не путай каналы перед отправкой.</p><p>Ссылка вида <code>[[tile:123]]</code> в сообщении создаёт карточку места. Пинг указывает клетку мира или координаты на текущей карте; в визите/live получателем по умолчанию может быть собеседник сессии. Используй пинг для координации, а не для передачи секретных данных.</p><p>Блокировка игрока запрещает сообщения, подарки, сделки и пинги между вами. Режим уведомлений и паузы на письмах настраивается отдельно.</p><h3 id="отправить-пинг" tabindex="-1">Отправить пинг <a class="header-anchor" href="#отправить-пинг" aria-label="Permalink to &quot;Отправить пинг&quot;">​</a></h3><p>Наведи мышь на место и нажми <strong>G</strong>; назначение меняется в <strong>Настройки → Клавиатура → Rimlink</strong>. На мировой карте выбирай клетку, на карте колонии — координаты. В визите/live получатель может выбираться как текущий напарник. Ввод в текстовом поле не посылает пинг. Получатель видит временную отметку (8 секунд); если её нет, проверь получателя, блокировку и лимит 12 пингов в минуту. Для постоянной ссылки в чате отправь <code>[[tile:123]]</code> с нужным номером клетки.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Публичный чат может пересылаться в Discord. Блокировка не запрещает рейды, рынок и визиты. Чат союза и личные сообщения не входят в публичный Discord-мост.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./community">Профили, друзья и союзы</a></li><li><a href="./live">Live: живая карта</a></li><li><a href="./../admins/discord">Discord-бот</a></li></ul>',12)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
